import {cropMap,cropPlan} from './crop-model.js';
import {clamp} from './model.js';

export function mapCropWorkshop(api){
  const $=s=>document.querySelector(s),esc=api.esc,state={active:false,rect:null};
  const controls=r=>[['nw',r.x,r.y],['n',r.x+r.width/2,r.y],['ne',r.x+r.width,r.y],['e',r.x+r.width,r.y+r.height/2],['se',r.x+r.width,r.y+r.height],['s',r.x+r.width/2,r.y+r.height],['sw',r.x,r.y+r.height],['w',r.x,r.y+r.height/2]];
  function begin(){state.active=true;state.rect={x:0,y:0,width:api.map().width,height:api.map().height};api.mode('crop');api.collapse();flow();api.draw();}
  function cancel(){state.active=false;state.rect=null;flow();api.mode('move');api.draw();}
  function flow(){const el=$('#cropFlow');el.hidden=!state.active;if(!state.active){el.innerHTML='';return;}const r=state.rect;el.innerHTML=`<div><b>Crop / resize · ${r.width} × ${r.height}</b><span>Drag an edge or corner. Drag inside to move the crop.</span></div><div class="flow-actions"><button id="cropNumbers" type="button" aria-label="Set exact map dimensions">Size</button><button id="applyCrop" type="button" class="primary">Apply</button><button id="cancelCrop" type="button" aria-label="Cancel resize">×</button></div>`;$('#cancelCrop').onclick=cancel;$('#applyCrop').onclick=review;$('#cropNumbers').onclick=numbers;}
  function numbers(){const r=state.rect;api.modal('Exact crop / resize',`<div class="field-row"><label>Left tile<input id="cropX" type="number" value="${r.x}" required></label><label>Top tile<input id="cropY" type="number" value="${r.y}" required></label></div><div class="field-row"><label>Width<input id="cropWidth" type="number" min="1" max="256" value="${r.width}" required></label><label>Height<input id="cropHeight" type="number" min="1" max="256" value="${r.height}" required></label></div><p>Negative Left or Top adds blank space on that side.</p>`,()=>{const rect={x:+$('#cropX').value,y:+$('#cropY').value,width:+$('#cropWidth').value,height:+$('#cropHeight').value};cropPlan(api.project(),api.map().id,rect);state.rect=rect;flow();api.draw();},'Preview size');}
  function review(){try{const p=cropPlan(api.project(),api.map().id,state.rect),count=Object.values(p.removed).reduce((n,v)=>n+v,0);api.modal('Apply '+p.rect.width+' × '+p.rect.height+' map',`<p>${api.map().width} × ${api.map().height} → <b>${p.rect.width} × ${p.rect.height} tiles</b>.</p><p>Kept map content, links and event destinations shift together. ${p.newCells?p.newCells+' new cells will be blank.':''}</p>${count?`<div class="callout">Outside the crop: ${p.removed.objects} objects, ${p.removed.markers} pins, ${p.removed.fields} HM objects and ${p.removed.gates} gates. These will be removed. Undo restores them.</div>`:'<p>No placed content will be removed.</p>'}${p.blockers.length?'<p class="error-text">Keep these exits / events inside the crop, or move them first:</p><ul>'+p.blockers.slice(0,12).map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul>':''}`,()=>{if(p.blockers.length)throw Error('Enlarge or move the crop to keep the listed endpoints inside.');const rect={...state.rect};api.change(()=>cropMap(api.project(),api.map().id,rect));state.active=false;state.rect=null;flow();api.applied(rect);api.mode('move');api.refresh();api.toast('Map resized. Undo restores the previous size and content.');},p.blockers.length?'Adjust crop first':'Apply size');if(p.blockers.length)$('#submitDialog').disabled=true;}catch(e){api.error(e);}}
  function start(point,g){const w=api.worldPoint(point),r=state.rect,margin=12/api.scale();let handle=controls(r).find(([,x,y])=>Math.hypot(w.x-x*16,w.y-y*16)<=margin)?.[0];if(!handle){const x=w.x/16,y=w.y/16;if(x>r.x&&x<r.x+r.width&&Math.abs(y-r.y)<margin/16)handle='n';else if(x>r.x&&x<r.x+r.width&&Math.abs(y-r.y-r.height)<margin/16)handle='s';else if(y>r.y&&y<r.y+r.height&&Math.abs(x-r.x)<margin/16)handle='w';else if(y>r.y&&y<r.y+r.height&&Math.abs(x-r.x-r.width)<margin/16)handle='e';else if(x>=r.x&&x<=r.x+r.width&&y>=r.y&&y<=r.y+r.height)handle='move';else handle='new';}g.kind='crop';g.cropHandle=handle;g.cropRect={...r};g.cropStart={x:w.x/16,y:w.y/16};}
  function move(point,g){const p=api.worldPoint(point),r=g.cropRect,h=g.cropHandle,dx=Math.round(p.x/16-g.cropStart.x),dy=Math.round(p.y/16-g.cropStart.y);let x=r.x,y=r.y,w=r.width,hh=r.height;if(h==='move'){x+=dx;y+=dy;}else if(h==='new'){x=Math.floor(Math.min(g.cropStart.x,p.x/16));y=Math.floor(Math.min(g.cropStart.y,p.y/16));w=clamp(Math.abs(Math.floor(p.x/16)-Math.floor(g.cropStart.x))+1,1,256);hh=clamp(Math.abs(Math.floor(p.y/16)-Math.floor(g.cropStart.y))+1,1,256);}else{if(h.includes('w')){const change=clamp(dx,r.width-256,r.width-1);x+=change;w-=change;}if(h.includes('e'))w=clamp(r.width+dx,1,256);if(h.includes('n')){const change=clamp(dy,r.height-256,r.height-1);y+=change;hh-=change;}if(h.includes('s'))hh=clamp(r.height+dy,1,256);}state.rect={x:clamp(x,-256,256),y:clamp(y,-256,256),width:w,height:hh};flow();api.draw();}
  function draw(c,map,scale){if(!state.active)return;const r=state.rect,x=r.x*16,y=r.y*16,w=r.width*16,h=r.height*16;c.save();c.fillStyle='#10291d88';c.beginPath();c.rect(-4096,-4096,12288,12288);c.rect(x,y,w,h);c.fill('evenodd');c.fillStyle='#d4eb8a18';c.fillRect(x,y,w,h);c.strokeStyle='#efffb3';c.lineWidth=2/scale;c.setLineDash([7/scale,4/scale]);c.strokeRect(x,y,w,h);c.setLineDash([]);for(const [,hx,hy]of controls(r)){const s=10/scale;c.fillStyle='#efffb3';c.strokeStyle='#243a2b';c.fillRect(hx*16-s/2,hy*16-s/2,s,s);c.lineWidth=1/scale;c.strokeRect(hx*16-s/2,hy*16-s/2,s,s);}c.font=`bold ${12/scale}px system-ui`;c.textAlign='center';c.fillStyle='#20372c';const label=r.width+' × '+r.height+' tiles',lw=c.measureText(label).width+16/scale;c.fillStyle='#efffb3';c.fillRect(x+w/2-lw/2,y-29/scale,lw,20/scale);c.fillStyle='#20372c';c.fillText(label,x+w/2,y-15/scale);c.restore();}
  return{state,begin,cancel,flow,review,start,move,draw};
}
